from helpers import macro_f1
k=np.load('kernel_v3.npz'); C,yc=k['C'],k['yc']
yb=np.load('base_feats.npz')['y']; print((yc[:1496]==yb).all())
Zp,yp=C[:1496],yc[:1496]; Zm,ym=C[1496:],yc[1496:]
d3=np.load('my3_feats.npz'); d4=np.load('my4_feats.npz')
Z3,y3,Z4,y4=d3['Z'],d3['y'],d4['Z'],d4['y']
def fitk(Ztr,ytr,wtr,lam):
    P=gelu(Ztr@Ztr.T/768); a,b=fit(P,ytr,wtr,lam); return a,b
def run_cv(extra, wx, lam, seeds=(0,1,2,3), nf=5):
    accs=[];f1s=[]
    for s in seeds:
        rng=np.random.default_rng(s); fo=np.zeros(1496,int)
        for c in range(8):
            idx=np.where(yp==c)[0]; rng.shuffle(idx); fo[idx]=np.arange(len(idx))%nf
        pred=np.zeros(1496,int)
        for f in range(nf):
            tr=fo!=f
            Zt=[Zp[tr]]+[e[0] for e in extra]; yt=[yp[tr]]+[e[1] for e in extra]
            wt=[np.ones(tr.sum())]+[np.full(len(e[1]),wx) for e in extra]
            Zt=np.concatenate(Zt); yt=np.concatenate(yt); wt=np.concatenate(wt)
            a,b=fitk(Zt,yt,wt,lam)
            pred[~tr]=np.argmax(gelu(Zp[~tr]@Zt.T/768)@a+b,1)
        accs.append((pred==yp).mean()); f1s.append(macro_f1(yp,pred))
    return np.mean(accs), np.mean(f1s), np.round(accs,4)
